test_suite:
test('type-level: extracts number return type', () => {
  type T = MyReturnType<() => number>;
  const check: T = 42;
  expect(check).toBe(42);
});

test('type-level: extracts string return type', () => {
  type T = MyReturnType<(s: string) => string>;
  const check: T = 'hello';
  expect(check).toBe('hello');
});

test('type-level: matches built-in ReturnType', () => {
  type Fn = (a: number, b: string) => boolean;
  type Check = MyReturnType<Fn> extends ReturnType<Fn> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: extracts object return type', () => {
  type T = MyReturnType<() => { id: number }>;
  const check: T = { id: 1 };
  expect(check.id).toBe(1);
});

// __hidden__
test('type-level: extracts void return type', () => {
  type T = MyReturnType<() => void>;
  type Check = T extends void ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});
